create table public.academy_pathways (level smallint primary key check (level between 1 and 3), title text not null, description text not null); create table public.academy_modules (slug text primary key, level smallint not null references public.academy_pathways(level), title text not null, position integer not null check(position>0), unique(level,position)); create table public.academy_module_lessons (module_slug text not null references public.academy_modules(slug), lesson_id uuid not null references public.lessons(id), position integer not null check(position>0), primary key(module_slug,lesson_id), unique(module_slug,position)); alter table public.academy_pathways enable row level security; alter table public.academy_modules enable row level security; alter table public.academy_module_lessons enable row level security; revoke all on public.academy_pathways,public.academy_modules,public.academy_module_lessons from public,anon,authenticated; grant select on public.academy_pathways,public.academy_modules,public.academy_module_lessons to authenticated; create policy pathways_paid on public.academy_pathways for select to authenticated using ((select public.has_paid_access(auth.uid()))); create policy modules_paid on public.academy_modules for select to authenticated using ((select public.has_paid_access(auth.uid()))); create policy module_lessons_paid on public.academy_module_lessons for select to authenticated using ((select public.has_paid_access(auth.uid())) and exists(select 1 from public.lessons l where l.id=lesson_id)); insert into public.academy_pathways values (1,'Foundation','Essential kitchen skills'),(2,'Professional Cookery','Professional kitchen techniques'),(3,'Advanced Cookery','Advanced techniques and management'); insert into public.academy_modules values ('hygiene',1,'Kitchen hygiene and safety',1),('knife-skills',1,'Knife skills',2),('preparation',1,'Mise en place',3),('cooking-methods',1,'Basic cooking methods',4),('stocks-sauces',2,'Stocks and sauces',1),('protein',2,'Meat, poultry and fish',2),('vegetables',2,'Vegetables and plant-based cookery',3),('pastry',2,'Pastry and baking',4),('allergens',2,'Allergen management',5),('advanced-techniques',3,'Advanced cookery techniques',1),('menu-development',3,'Menu development',2),('costing',3,'Food costing and stock control',3),('leadership',3,'Kitchen leadership',4); insert into public.academy_module_lessons(module_slug,lesson_id,position) select case l.title when 'Kitchen hygiene fundamentals' then 'hygiene' when 'Knife skills and safety' then 'knife-skills' when 'Mise en place' then 'preparation' end,l.id,1 from public.lessons l join public.academy_catalogue c on c.lesson_id=l.id where l.title in ('Kitchen hygiene fundamentals','Knife skills and safety','Mise en place');
